function guideForms(root=document){if(!root)return;for(const form of root.querySelectorAll('form,.filter-panel')){form.noValidate=true;for(const n of form.querySelectorAll('input:not([type=hidden]),select,textarea')){if(n.dataset.guided||n.closest('[data-selector]')||(n.type==='checkbox'&&['benefits','filter-benefits','services'].includes(n.name))||['button','submit','radio'].includes(n.type))continue;const label=n.closest('label');if(!label)continue;n.dataset.guided='true';const name=n.name;if(name==='email'&&['candidate-form','employer-form'].includes(form.id))n.required=false;let g=formHints[name.replace('filter-','')]||[n.tagName==='SELECT'?'Choose the option for this request.':'Provide '+(label.childNodes[0]?.textContent||name).trim().toLowerCase()+' relevant to this request.','','संबंधित विवरण भरें।'];if(n.type==='checkbox')g=[({consent:'Accept the privacy policy and terms before continuing.',consent_to_share:'Allow this salon to receive your application and contact details.',is_urgent:'Enable only if you need the position filled urgently.',contact_public:'Display the number above publicly.',requires_resume:'Applicants must provide a CV when enabled.',negotiable:'Enable if willing to discuss the salary.',discoverable:'Allow employers to find your profile.',alerts_enabled:'Receive alerts matching your selected roles.'})[name]||'Enable only if this option applies.','','यह विकल्प लागू हो तभी चुनें।'];if(name==='primary_category_id'){label.childNodes[0].textContent=t('Job Title — Which staff member do you want to hire?','जॉब का शीर्षक — किस कर्मचारी को रखना चाहते हैं?');n.options[0].textContent=t('Select the staff role you want to hire','जिस कर्मचारी की ज़रूरत है उसे चुनें');g=["Select the type of professional you need for your salon. For example, choose Beautician if you want to hire a beautician, or Gents Hairdresser if you need a men's hair stylist.",'','सैलून के लिए भूमिका चुनें, जैसे Beautician या Gents Hairdresser।'];if(!categories.some(c=>c.is_active)){const error=document.createElement('p');error.className='field-error';error.textContent='Job roles could not load. Check your connection and retry.';const retry=document.createElement('button');retry.type='button';retry.className='secondary';retry.textContent='Retry loading job roles';retry.onclick=async()=>{retry.disabled=true;try{categories=await read('categories','order=sort_order.asc,name.asc&limit=500');const value=n.value;n.innerHTML='<option value="">Select the staff role you want to hire</option>'+categories.filter(c=>c.is_active||c.id===form.dataset.primaryHistory).map(c=>`<option value="${e(c.id)}">${e(c.name)}</option>`).join('');n.value=value;error.remove();retry.remove();}catch(err){error.textContent=err.message;}finally{retry.disabled=false;}};label.append(error,retry);}}if(name==='description'&&form.id==='post-form')g=['Describe the job duties and services required. Example: We are looking for an experienced Gents Hairdresser who can perform haircuts, beard trimming, shaving, and customer grooming services.','Describe duties and services for this vacancy','जॉब के काम और ज़रूरी सेवाएँ लिखें।'];const hint=document.createElement('small');hint.id=`hint-${form.id}-${name}`;hint.className='field-hint';hint.textContent=t(g[0],g[2]);label.append(hint);if(n.type!=='checkbox'){const marker=document.createElement('span');marker.className='field-marker';marker.textContent=n.required?t('Required','ज़रूरी'):t('Optional','वैकल्पिक');label.insertBefore(marker,n);}if(g[1]&&!n.placeholder)n.placeholder=g[1];if(['vacancies','positions','outlets'].includes(name))n.min='1';if(n.type==='number'){n.inputMode='numeric';if(!n.max)n.max='2147483647';}if(name==='application_deadline')n.min=localISODate();let err=label.querySelector('[data-field-error]');if(!err){err=document.createElement('small');err.className='field-error';err.dataset.fieldError=name;label.append(err);}err.id=`error-${form.id}-${name}`;err.setAttribute('role','alert');n.setAttribute('aria-describedby',hint.id+' '+err.id);}}}
const formModal=modal;modal=function(...args){formModal(...args);guideForms();};new MutationObserver(()=>guideForms()).observe(document.body,{childList:true,subtree:true});guideForms();
function focusFormError(form,n){if(form.id==='candidate-form'){const step=n.closest('[data-wizard-step]');if(step)showStep(Number(step.dataset.wizardStep));}n.scrollIntoView?.({behavior:'smooth',block:'center'});n.focus({preventScroll:true});}
validateFields=function(form,step=null){guideForms();form.querySelectorAll('.field-error').forEach(n=>n.textContent='');form.querySelector('[data-form-error]')?.replaceChildren();const scope=step?form.querySelector(`[data-wizard-step="${step}"]`):form;let first;const bad=(n,msg)=>{if(!n)return;n.setAttribute('aria-invalid','true');const err=form.querySelector(`[data-field-error="${n.name}"]`);if(err)err.textContent=msg;first=first||n;};for(const n of scope.querySelectorAll('input,select,textarea')){n.removeAttribute('aria-invalid');if(n.type==='hidden')continue;let msg='';if(n.name==='primary_category_id'&&!n.value)msg='Please select the job role you want to hire.';else if(n.required&&(n.type==='checkbox'&&!n.checked||!['checkbox','radio','file'].includes(n.type)&&!n.value.trim()))msg=n.type==='checkbox'?'Please confirm this before continuing.':'Please complete this required field.';else if(n.type==='file'&&[...n.files].some(f=>f.size>(n.name==='logo'?2:5)*1024*1024))msg='File is too large. Maximum '+(n.name==='logo'?2:5)+' MB per file.';else if(n.type==='file'&&n.accept&&[...n.files].some(f=>f.type&&!n.accept.split(',').includes(f.type)))msg='Choose a supported file type.';else if(!n.checkValidity())msg=n.type==='email'?'Enter a valid email address, such as you@example.com.':n.type==='number'?'Enter a whole number within the allowed range.':n.type==='tel'?'Enter a valid mobile number: 10 digits, or include your country code.':n.validationMessage;if(msg)bad(n,msg);}const el=name=>form.elements?.[name]||form.querySelector(`[name="${name}"]`);if(!step){for(const [min,max] of [['salary_min','salary_max'],['experience_min','experience_max'],['talent-min','talent-max']])if(el(max)?.value&&el(min)&&Number(el(max).value)<Number(el(min).value))bad(el(max),max==='salary_max'?'Maximum salary must be at least the minimum salary.':'Maximum experience must be at least the minimum experience.');if(el('gender_preference')&&el('gender_preference').value!=='Any'&&el('preference_justification').value.trim().length<10)bad(el('preference_justification'),'Explain the job-specific reason using at least 10 characters.');if(el('contact_public')?.checked&&!el('public_phone')?.value.trim())bad(el('public_phone'),'Enter an authorized phone number before making it public.');if(el('scheduled_at')?.value&&new Date(el('scheduled_at').value)<=new Date())bad(el('scheduled_at'),'Choose a future interview time.');if(el('screening_questions')?.value.split('\n').filter(x=>x.trim()).length>20)bad(el('screening_questions'),'Use at most 20 screening questions.');if(el('faqs')?.value.split('\n').filter(x=>x.trim()).some(x=>!x.includes('|')||x.split('|').some(y=>!y.trim())))bad(el('faqs'),'Use Question | Answer with both parts filled in.');}const sel=scope.querySelector('[data-selector][data-required="true"]');if(sel&&!selected(sel).length){sel.open=true;let err=sel.querySelector('.selection-error');if(!err){err=document.createElement('p');err.className='selection-error field-error';err.setAttribute('role','alert');sel.append(err);}err.textContent='Select at least one job profile.';first=first||sel.querySelector('summary');}if(first){focusFormError(form,first);return false;}return true;};
document.addEventListener('submit',ev=>{ev.target._lastSubmitter=ev.submitter;},true);
runSubmit=async function(form,work){if(form.dataset.busy==='true'||!validateFields(form))return;form.dataset.busy='true';form.setAttribute('aria-busy','true');const buttons=[...form.querySelectorAll('[type=submit]')],labels=buttons.map(b=>b.textContent);buttons.forEach(b=>{b.disabled=true;b.textContent=t('Saving…','सहेज रहे हैं…');});form.querySelector('[data-submit-retry]')?.remove();try{await work();}catch(err){const message=/failed to fetch|networkerror/i.test(err.message)?'Nexora could not be reached. Check your connection and retry.':String(err.message||'Check your connection and retry.');const mapping=[[/salary/i,'salary_max'],[/vacanc/i,'vacancies'],[/job title|categor/i,'primary_category_id'],[/mobile/i,'mobile'],[/resume/i,'resume'],[/screening/i,'screening_questions']].find(([rx,key])=>rx.test(message)&&form.querySelector(`[data-field-error="${key}"]`));if(mapping){const n=form.querySelector(`[name="${mapping[1]}"]`);form.querySelector(`[data-field-error="${mapping[1]}"]`).textContent=message;n?.setAttribute('aria-invalid','true');if(n)focusFormError(form,n);}formError(form,/duplicate key/i.test(message)?'This record already exists. Check your dashboard before retrying.':message);const retry=document.createElement('button');retry.type='button';retry.className='secondary';retry.dataset.submitRetry='true';retry.textContent=t('Retry submission','फिर से भेजें');retry.onclick=()=>form.requestSubmit(form._lastSubmitter||undefined);form.querySelector('[data-form-error]').after(retry);}finally{form.dataset.busy='false';form.removeAttribute('aria-busy');buttons.forEach((b,i)=>{b.disabled=false;b.textContent=labels[i];});}};
document.addEventListener('click',ev=>{if(ev.target.closest('[data-action="apply-filters"]')){const panel=document.querySelector('#filters');if(panel&&!validateFields(panel)){ev.preventDefault();ev.stopImmediatePropagation();}}},true);
